package com.vocal.controller;
import com.vocal.dto.ProductDtos.*; import com.vocal.service.ProductService; import io.swagger.v3.oas.annotations.tags.Tag; import lombok.RequiredArgsConstructor; import org.springframework.data.domain.*; import org.springframework.web.bind.annotation.*; import java.math.BigDecimal; import java.util.*;
@RestController @RequestMapping("/api/public") @RequiredArgsConstructor @Tag(name="Public catalog") public class PublicCatalogController { private final ProductService products; @GetMapping("/home") Object home(){return products.home();} @GetMapping("/products") Page<ProductResponse> search(@RequestParam(required=false) String q,@RequestParam(required=false) String category,@RequestParam(required=false) BigDecimal min,@RequestParam(required=false) BigDecimal max, Pageable pageable){return products.search(q,category,min,max,pageable);} @GetMapping("/products/{slug}") ProductResponse detail(@PathVariable String slug){return products.bySlug(slug);} @GetMapping("/categories") List<CategoryResponse> categories(){return products.categories();} }
